"""Conversion helpers for Taplo's toml-test decoder command."""
from datetime import date, datetime, time
from decimal import Decimal
import json


def tagged(value):
    if isinstance(value, bool):
        kind, raw = "bool", "true" if value else "false"
    elif isinstance(value, int):
        kind, raw = "integer", str(value)
    elif isinstance(value, float):
        kind, raw = "float", float_text(value)
    elif isinstance(value, str):
        kind, raw = "string", value
    elif isinstance(value, datetime):
        kind = "datetime" if value.tzinfo is not None else "datetime-local"
        raw = json.dumps(trim_fraction(value.isoformat().replace("+00:00", "Z")))
    elif isinstance(value, date):
        kind, raw = "date-local", json.dumps(value.isoformat())
    elif isinstance(value, time):
        kind, raw = "time-local", json.dumps(trim_fraction(value.isoformat()))
    elif isinstance(value, list):
        return [tagged(item) for item in value]
    elif isinstance(value, dict):
        return {key: tagged(item) for key, item in value.items()}
    else:
        raise TypeError(type(value).__name__)
    return {"type": kind, "value": raw}


def trim_fraction(value: str) -> str:
    """Trim insignificant trailing zeros from a fractional second."""
    dot = value.find(".")
    if dot < 0:
        return value
    end = dot + 1
    while end < len(value) and value[end].isdigit():
        end += 1
    fraction = value[dot + 1:end].rstrip("0")
    if not fraction:
        return value[:dot] + value[end:]
    return value[:dot + 1] + fraction + value[end:]


def float_text(value: float) -> str:
    """Use the compact decimal spelling emitted by Taplo's TOML decoder."""
    if value != value:
        return "nan"
    if value == float("inf"):
        return "inf"
    if value == float("-inf"):
        return "-inf"
    raw = repr(value)
    if "e" not in raw:
        return raw
