    # Taplo uses fixed notation from 1e-5 through values below 1e16.
    if -5 <= exponent < 16:
        fixed = format(Decimal(raw), "f")
        return fixed if "." in fixed else fixed + ".0"
    mantissa = raw.split("e")[0]
    return f"{mantissa}e{exponent}"


def encode(document) -> str:
    """Encode an already parsed TOML document as compact toml-test JSON."""
    return json.dumps(tagged(document), ensure_ascii=False, separators=(",", ":"))
