def _toml_doc(v):
    if isinstance(v, InlineTable):
        return _toml_value(v)
    if isinstance(v, list) and v and all(isinstance(x, dict) and not isinstance(x, InlineTable) for x in v):
        blocks = []
        for table in v:
            lines = ["[[]]"]
            lines.extend(f"{_toml_key(k)} = {_toml_value(x)}" for k, x in table.items())
            blocks.append("\n".join(lines))
        return "\n".join(blocks)
    if isinstance(v, dict):
        return "\n".join(f"{_toml_key(k)} = {_toml_value(x)}" for k, x in v.items())
    return _toml_value(v)

